#!/usr/bin/env node
'use strict';
/*
 * Explicit, ROM-bound bridge for projects whose historical CFG coverage was
 * generated by an older Forja65 decoder. Never relabel an old cache as new.
 * Runs the matching legacy generator in a staging copy and copies only CPU CFG
 * outputs into the current project, preserving its stable custom runtime.
 */
const fs=require('node:fs'),path=require('node:path'),os=require('node:os'),cp=require('node:child_process');
const Current=require('../forja65-core.js');
const IO=require('./project-io.js');
const Audit=require('./dispatch-frontier-audit.js');
function args(argv){const o={};for(let i=0;i<argv.length;i++){
 const k=argv[i];if(k==='--check'){o.check=true;continue;}
 if(!['--project','--legacy-forja','--from','--max'].includes(k)||i+1>=argv.length)throw Error('Invalid argument '+k);
 o[k.slice(2)]=argv[++i];}
 if(!o.project||!o['legacy-forja']||!o.from)throw Error('Usage: node tools/legacy-cfg-bridge.js --project PATH --legacy-forja MATCHING_FORJA_DIR --from DIAGNOSTIC_DIR [--max 12000] [--check]');
 o.project=path.resolve(o.project);o.legacy=path.resolve(o['legacy-forja']);o.from=path.resolve(o.from);return o;}
function readJson(p){return JSON.parse(fs.readFileSync(p,'utf8'));}
function validate(o){
 const cache=readJson(path.join(o.project,'analysis/cfg-coverage-cache.json'));
 const opts=readJson(path.join(o.project,'analysis/generation-options.json'));
 const legacyCore=require(path.join(o.legacy,'forja65-core.js'));
 if(cache.version!==legacyCore.VERSION)throw Error('Legacy generator mismatch: cache='+cache.version+' engine='+legacyCore.VERSION);
 const cart=Current.loadRom(new Uint8Array(fs.readFileSync(path.join(o.project,'assets/cart-data.bin'))),'cart-data.bin');
 const rom=Current.romFingerprint(cart);
 if(!/^[0-9a-f]{16}$/.test(rom)||rom!==opts.rom||rom!==cache.rom)throw Error('ROM fingerprint mismatch; refusing CFG import');
 const diagnostics=fs.readFileSync(path.join(o.from,'forja65-runtime-hints.txt'),'utf8');
 const hints=Current.parseRuntimeHints(diagnostics);
 if(!hints.length||hints.some(h=>h.rom!==rom))throw Error('No valid matching-ROM evidence');
 const old=fs.readFileSync(path.join(o.project,'analysis/runtime-hints.txt'),'utf8');
 const a=Audit.auditRuntimeEvidence(diagnostics,old,Audit.parseDispatch(fs.readFileSync(path.join(o.project,'src/dispatch.cpp'),'utf8')),rom);
 if(a.stale_rom_hints||a.malformed_lines.length||a.excluded_non_rom.length)throw Error('Unsafe runtime evidence');
 const max=o.max===undefined?opts.max:Number(o.max);
 if(!Number.isSafeInteger(max)||max<1||max>1000000)throw Error('Invalid analysis max');
 return {rom,cache_version:cache.version,current_version:Current.VERSION,legacy_version:legacyCore.VERSION,unlearned:a.unlearned,uncompiled:a.uncompiled,max,cacheLimit:opts.cacheLimit};
}
function run(o){
 const initial=validate(o);
 if(o.check)return {status:'CHECK_ONLY',...initial};
 if(!initial.unlearned&&!initial.uncompiled)return {status:'ALREADY_COVERED',...initial};
 const tmp=fs.mkdtempSync(path.join(os.tmpdir(),'forja65-legacy-cfg-'));
 try{
  const stage=path.join(tmp,'project');
  fs.cpSync(o.project,stage,{recursive:true,filter:p=>{
   const rel=path.relative(o.project,p).replaceAll('\\','/');
   return !rel.split('/').some(x=>/^build($|-)|^diagnosticos/.test(x));
  }});
  const cli=path.join(o.legacy,'tools/forja65.js');
  const command=[cli,'learn-crash',stage,'--from',o.from,'--max',String(initial.max),'--cache-limit',String(initial.cacheLimit)];
  const child=cp.spawnSync(process.execPath,command,{encoding:'utf8',maxBuffer:8*1024*1024,timeout:180000});
  if(child.error||child.status!==0)throw Error('Legacy CFG learn failed: '+(child.stderr||child.stdout||child.error?.message||'unknown error').trim());
  const stagedHints=fs.readFileSync(path.join(stage,'analysis/runtime-hints.txt'),'utf8');
  const stagedDispatch=fs.readFileSync(path.join(stage,'src/dispatch.cpp'),'utf8');
  const check=Audit.auditRuntimeEvidence(fs.readFileSync(path.join(o.from,'forja65-runtime-hints.txt'),'utf8'),stagedHints,Audit.parseDispatch(stagedDispatch),initial.rom);
  if(check.unlearned||check.uncompiled||check.stale_rom_hints||check.malformed_lines.length)throw Error('Staged dispatcher does not cover observed evidence');
  const files=['src/dispatch.cpp','src/generated.hpp','analysis/cfg-coverage-cache.json','analysis/function-analysis.json','analysis/native-map.json','analysis/native-map.md','analysis/runtime-hints.txt','analysis/generation-options.json','reports/learn-crash.json','reports/cfg-discovery-budget.json'];
  for(const file of fs.readdirSync(path.join(stage,'src')))if(/^generated_\d{3}\.cpp$/.test(file))files.push('src/'+file);
  const replaced={};for(const n of files){const p=path.join(stage,n);if(fs.existsSync(p))replaced[n]=fs.readFileSync(p);}
  const original={};for(const n of Object.keys(replaced)){const p=path.join(o.project,n);original[n]=fs.existsSync(p)?fs.readFileSync(p):null;}
  let updated=0;
  try{
   for(const [n,data]of Object.entries(replaced)){
    const out=path.join(o.project,n);if(original[n]&&original[n].equals(data))continue;
    fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,data);updated++;
   }
   const kept={};for(const n of ['src/runtime.hpp','src/main.cpp','src/native_hooks.cpp','CMakeLists.txt']){const p=path.join(o.project,n);if(fs.existsSync(p))kept[n]=fs.readFileSync(p);}
   IO.refreshManifest(o.project,{...replaced,...kept});
  }catch(err){for(const [n,data]of Object.entries(original)){const p=path.join(o.project,n);if(data===null)fs.rmSync(p,{force:true});else fs.writeFileSync(p,data);}throw err;}
  return {status:'LEARNED_STAGED',...initial,changed_files:updated,unlearned_after:check.unlearned,uncompiled_after:check.uncompiled,limits:'Compilation and replay validation must follow; historical cache remains on its original version.'};
 }finally{fs.rmSync(tmp,{recursive:true,force:true});}
}
if(require.main===module){try{console.log(JSON.stringify(run(args(process.argv.slice(2))),null,2));}catch(e){console.error('Forja65 legacy bridge: '+e.message);process.exitCode=2;}}
module.exports={args,validate,run};
